import{_ as n,l,o as e,c as s,v as t,p as i,x as r,d,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"2-SAT","description":"","frontmatter":{"title":"2-SAT","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/two-sat.md","filePath":"cs/two-sat.md","lastUpdated":1789023840000}'),C={name:"cs/two-sat.md"};function A(c,a,T,x,S,_){const o=l("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="_2-sat" tabindex="-1">2-SAT <a class="header-anchor" href="#_2-sat" aria-label="Permalink to &quot;2-SAT&quot;">​</a></h1><div class="epigraph"><p>每个子句两个文字时，可满足性落到蕴涵图的强连通分量上：变量与其否定若同块则无解，否则按拓扑赋真假。</p><footer>—— 据 Aspvall, Plass and Tarjan, A Linear-Time Algorithm for Testing the Truth of Certain Quantified Boolean Formulas, 1979；CLRS 第 22 章整理</footer></div><p>上一课<a href="/cs/scc-tarjan">强连通分量</a>给出线性 SCC 与缩点 DAG。主干<a href="/cs/sat-3sat">SAT 与 3-SAT</a>把三元子句钉在 NPC。缺口是<strong>二元子句</strong>：\\((x\\lor y)\\) 等价于 \\((\\neg x\\to y)\\land(\\neg y\\to x)\\)。把每个文字当顶点、蕴涵当有向边，SCC 决定可否满足。本课不重写 3-SAT 完全性，也不把 DPLL 请回来。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>2-CNF：子句皆二元（可含单文字，补假文字即可）。蕴涵图：顶点 \\(x\\) 与 \\(\\neg x\\)；子句 \\((a\\lor b)\\) 加边 \\(\\neg a\\to b\\)、\\(\\neg b\\to a\\)。赋值使文字为真，当且仅当不沿蕴涵走到假。关键：若某 \\(x\\) 与 \\(\\neg x\\) 落在同一 SCC，则无解；否则一定有解。</p><p>缺口是这层翻译，不是再跑一遍 Kosaraju 的证明。3-SAT 每个子句三个文字，没有「两向蕴涵」这种线性图；不要把本课算法套到 3-CNF。</p><h3 id="赋值沿着缩点-dag" tabindex="-1">赋值沿着缩点 DAG <a class="header-anchor" href="#赋值沿着缩点-dag" aria-label="Permalink to &quot;赋值沿着缩点 DAG&quot;">​</a></h3><p>可满足时：在缩点 DAG 上拓扑，若 \\(\\mathrm{SCC}(\\neg x)\\) 排在 \\(\\mathrm{SCC}(x)\\) 之后则令 \\(x\\) 真（或对称约定）。同一块内文字同真同假，故块内不能同时有 \\(x\\) 与 \\(\\neg x\\)。实现上常：若 \\(\\mathrm{id}[x]\\lt \\mathrm{id}[\\neg x]\\) 则 \\(x\\) 假，其中 <code>id</code> 为拓扑序编号。</p><p><span class="marginnote">Aspvall–Plass–Tarjan 1979 把 2-SAT（及若干带量词的变体）收到线性。Horn-SAT 另有单位传播多项式，本课不混。后课欧拉回路换对象：边的遍历，不是文字。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>建 \\(2n\\) 个顶点。每条子句两条蕴涵。算 SCC。若存在 \\(i\\) 使 \\(x_i\\) 与 \\(\\neg x_i\\) 同块，输出不可满足。否则按缩点拓扑赋每个变量。总 \\(\\Theta(n+m)\\)。</p>',11)),(e(),i(p,null,{default:r(()=>[h(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20CNF%5B%222-CNF%22%5D%20--%3E%20IMP%5B%22%E8%95%B4%E6%B6%B5%E5%9B%BE%22%5D%0A%20%20IMP%20--%3E%20SCC%5B%22SCC%22%5D%0A%20%20SCC%20--%3E%20BAD%5B%22x%20%E4%B8%8E%20%C2%ACx%20%E5%90%8C%E5%9D%97%EF%BC%9F%22%5D%0A%20%20BAD%20--%3E%7C%22%E6%98%AF%22%7C%20UNSAT%5B%22%E4%B8%8D%E5%8F%AF%E6%BB%A1%E8%B6%B3%22%5D%0A%20%20BAD%20--%3E%7C%22%E5%90%A6%22%7C%20TOPO%5B%22%E6%8B%93%E6%89%91%E8%B5%8B%E5%80%BC%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>差分约束 \\(x_j-x_i\\le c\\) 化成边，可行当且仅当无负环——与本课不同图；本课只布尔。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>强连通意味着互相蕴涵：一块里一个真则全体真。\\(x\\) 与 \\(\\neg x\\) 同块即推出矛盾。缩点 DAG 无环，故可以「先假后真」地沿拓扑放赋值，不会回头推翻。与<a href="/cs/propositional-logic-cnf">命题逻辑 CNF</a> 的语义相同，算法换成图。</p><p>不要用随机赋值或分辨率当本课的主算法：正确但不是线性结构。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不解 3-SAT、不解 MAX-2-SAT 的优化版（后者 NP-hard）。不写 QBF 的完整 APT 算法。后课默认：2-SAT = 蕴涵图 SCC。下一课问的是边能否一笔画，不是子句。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>\\((a\\lor b)\\) 变成两条蕴涵；SCC 里 \\(x\\) 与 \\(\\neg x\\) 不能同块。</li><li>可满足则按缩点拓扑赋值，线性时间。</li><li>三元子句没有这张图。</li><li>出处：Aspvall, Plass and Tarjan, 1979；SCC 见 Tarjan, 1972。</li></ul>',8))])}const u=n(C,[["render",A]]);export{B as __pageData,u as default};
